WITH customer_summary AS (SELECT customer_id, COUNT(monthly_fee) monthly_fee_count, AVG(monthly_fee) avg_monthly_fee FROM subscriptions WHERE start_date < '2023-11-02' GROUP BY customer_id) SELECT customers.id, customers.segment, customer_summary.monthly_fee_count, customer_summary.avg_monthly_fee FROM customers LEFT JOIN customer_summary ON customers.id = customer_summary.customer_id;
